namespace sv_7a91a19f394c412f8478dd47f3df151f.Services;

/// <summary>
/// Scoped service (one per SignalR circuit) that holds the currently selected warehouse
/// and notifies all subscribers when the selection changes.
/// </summary>
public class WarehouseStateService : IDisposable
{
    private string _currentWarehouseId = "WH-001";

    public string CurrentWarehouseId
    {
        get => _currentWarehouseId;
        set
        {
            if (_currentWarehouseId != value)
            {
                _currentWarehouseId = value;
                NotifyStateChanged();
            }
        }
    }

    public string CurrentWarehouseName =>
        Warehouses.FirstOrDefault(w => w.Id == _currentWarehouseId)?.Name ?? "Unknown";

    public static IReadOnlyList<Warehouse> Warehouses { get; } = new List<Warehouse>
    {
        new("WH-001", "Warehouse A - Downtown"),
        new("WH-002", "Warehouse B - Airport"),
        new("WH-003", "Warehouse C - Harbor"),
    };

    public event Action? OnChange;

    private void NotifyStateChanged() => OnChange?.Invoke();

    public void Dispose()
    {
        // Clear all subscribers to prevent memory leaks when the circuit ends.
        OnChange = null;
    }
}

public record Warehouse(string Id, string Name);

namespace sv_7a91a19f394c412f8478dd47f3df151f.Services;

/// <summary>
/// Scoped service that manages low-stock alert polling and notifies all
/// subscribed components when new data arrives.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly WarehouseStateService _warehouseState;
    private readonly Random _random = new();
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;

    public int CurrentLowStockCount { get; private set; }

    public event Action? OnAlertDataChanged;

    public InventoryAlertService(WarehouseStateService warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChange += HandleWarehouseChanged;
    }

    /// <summary>
    /// Simulates a database query returning low-stock item count for a warehouse.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Called by components to start polling. Uses reference counting so polling
    /// stays active as long as at least one component is subscribed.
    /// </summary>
    public void StartPolling()
    {
        _subscriberCount++;
        if (_subscriberCount == 1)
        {
            _cts = new CancellationTokenSource();
            _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
            _ = PollLoopAsync(_cts.Token);
        }
    }

    /// <summary>
    /// Called by components when they are disposed. Stops polling when no
    /// subscribers remain.
    /// </summary>
    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount == 0)
        {
            _cts?.Cancel();
            _timer?.Dispose();
            _timer = null;
        }
    }

    /// <summary>
    /// Forces an immediate poll (e.g., after warehouse change).
    /// </summary>
    public async Task RefreshAsync()
    {
        CurrentLowStockCount = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
        NotifySubscribers();
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Do an initial fetch immediately.
        await RefreshAsync();

        while (_timer is not null)
        {
            try
            {
                if (!await _timer.WaitForNextTickAsync(ct))
                    break;
            }
            catch (OperationCanceledException)
            {
                break;
            }

            CurrentLowStockCount = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
            NotifySubscribers();
        }
    }

    private void HandleWarehouseChanged()
    {
        if (_subscriberCount > 0)
        {
            _ = RefreshAsync();
        }
    }

    private void NotifySubscribers() => OnAlertDataChanged?.Invoke();

    public void Dispose()
    {
        _warehouseState.OnChange -= HandleWarehouseChanged;
        _cts?.Cancel();
        _timer?.Dispose();
        OnAlertDataChanged = null;
    }
}

