@using sv_7a91a19f394c412f8478dd47f3df151f.Services
@rendermode InteractiveServer
@inject WarehouseStateService WarehouseState
@implements IDisposable

<div class="warehouse-selector">
    <label for="warehouse-dropdown"><strong>Warehouse:</strong></label>
    <select id="warehouse-dropdown" class="form-select form-select-sm d-inline-block w-auto ms-2"
            value="@WarehouseState.CurrentWarehouseId"
            @onchange="OnWarehouseChanged">
        @foreach (var wh in WarehouseStateService.Warehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += StateHasChanged;
    }

    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        WarehouseState.CurrentWarehouseId = e.Value?.ToString() ?? "WH-001";
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= StateHasChanged;
    }
}

@using sv_7a91a19f394c412f8478dd47f3df151f.Services
@rendermode InteractiveServer
@inject InventoryAlertService AlertService
@implements IDisposable

<span class="alert-badge" title="Low-stock items">
    🔔
    @if (AlertService.CurrentLowStockCount > 0)
    {
        <span class="badge bg-danger rounded-pill">@AlertService.CurrentLowStockCount</span>
    }
    else
    {
        <span class="badge bg-success rounded-pill">0</span>
    }
</span>

@code {
    protected override void OnInitialized()
    {
        AlertService.OnAlertDataChanged += HandleAlertDataChanged;
    }

    private void HandleAlertDataChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertService.OnAlertDataChanged -= HandleAlertDataChanged;
    }
}

