@page "/dashboard"
@using sv_7a91a19f394c412f8478dd47f3df151f.Services
@rendermode InteractiveServer
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard - @WarehouseState.CurrentWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mt-3">
    <div class="card-body">
        <h5 class="card-title">Current Warehouse</h5>
        <p class="card-text fs-4">📍 @WarehouseState.CurrentWarehouseName</p>
    </div>
</div>

<div class="card mt-3">
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        <p class="card-text">
            @if (AlertService.CurrentLowStockCount > 0)
            {
                <span class="text-danger fs-4">
                    ⚠️ @AlertService.CurrentLowStockCount items below minimum stock level
                </span>
            }
            else
            {
                <span class="text-success fs-4">
                    ✅ All items are at or above minimum stock levels
                </span>
            }
        </p>
        <small class="text-muted">Refreshes every 10 seconds</small>
    </div>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += HandleStateChanged;
        AlertService.OnAlertDataChanged += HandleAlertDataChanged;

        // Start polling when the dashboard becomes visible.
        AlertService.StartPolling();
    }

    private void HandleStateChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private void HandleAlertDataChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= HandleStateChanged;
        AlertService.OnAlertDataChanged -= HandleAlertDataChanged;

        // Stop polling when the user leaves the dashboard page.
        AlertService.StopPolling();
    }
}

